namespace Alchemy\Phrasea\Metadata\Tag;

use Alchemy\Phrasea\Metadata\TagFactory;
use PHPExiftool\Driver\AbstractTagGroup;
use PHPExiftool\Driver\TagGroupFactory;
use PHPExiftool\Driver\TagGroupInterface;

/**
 * Exposes a tag group generated by phpexiftool as a Phraseanet tag.
 *
 * Serialized by tag name: generated classes are not autoloadable and could not be unserialized.
 */
class ExiftoolTag extends AbstractTag
{
    private TagGroupInterface $tagGroup;

    public function __construct(TagGroupInterface $tagGroup)
    {
        $this->tagGroup = $tagGroup;
    }

    public function getTagGroup(): TagGroupInterface
    {
        return $this->tagGroup;
    }

    public function getId(): string
    {
        return $this->tagGroup->getId();
    }

    public function getWriteKey(): string
    {
        return $this->tagGroup instanceof AbstractTagGroup ? $this->tagGroup->getWriteKey() : $this->tagGroup->getId();
    }

    public function getName(): string
    {
        return $this->tagGroup->getName();
    }

    public function getDescription(string $lng = 'en'): ?string
    {
        return $this->tagGroup->getDescription($lng);
    }

    public function isMulti(): bool
    {
        return $this->tagGroup->isMulti();
    }

    public function isBinary(): bool
    {
        return $this->tagGroup->isBinary();
    }

    public function getPhpType(): ?string
    {
        return $this->tagGroup->getPhpType();
    }

    public function isWritable(): bool
    {
        return $this->tagGroup->isWritable();
    }

    public function getMaxLength(): int
    {
        return $this->tagGroup->getMaxLength();
    }

    public function __serialize(): array
    {
        return ['id' => $this->tagGroup->getId()];
    }

    public function __unserialize(array $data): void
    {
        $this->tagGroup = TagGroupFactory::getFromRDFTagname(TagFactory::getClassesDirectory(), $data['id']);
    }
}
